+        );
+        assertThat(ex.getMessage(), is("Incorrect format for line [8.0.,f4d2]"));
+    }
+
+    @Test
+    public void testFailsDuplicateVersions() {
+        List<String> lines = List.of("8.0.0,100", "8.0.0,101");
